contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();

        uint256 deposited = address(c).balance;

        bool reverted;
        if (withdrawAmount > deposited) {
            try c.withdraw(withdrawAmount) { reverted = false; } catch { reverted = true; }
        } else {
            c.withdraw(withdrawAmount);
            reverted = false;
        }

        uint256 remaining = address(c).balance;
        assert(!reverted || withdrawAmount > deposited);
        assert(reverted || remaining == deposited - withdrawAmount);
    }

    receive() external payable {}
}

