contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount > 0 && depositAmount <= address(this).balance);

        uint balBefore = c.balances(address(this));
        c.deposit{value: depositAmount}();
        uint balAfterDeposit = c.balances(address(this));
        require(balAfterDeposit == balBefore + depositAmount);

        uint contractBalBefore = address(c).balance;
        bool reverted;
        if (withdrawAmount == depositAmount) {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore - depositAmount);
        } else {
            uint effectiveWithdraw = withdrawAmount;
            if (effectiveWithdraw > balAfterDeposit) {
                try c.withdraw(effectiveWithdraw) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                assert(reverted && c.balances(address(this)) == balAfterDeposit && address(c).balance == contractBalBefore);
            } else {
                try c.withdraw(effectiveWithdraw) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                assert(!reverted && c.balances(address(this)) == balAfterDeposit - effectiveWithdraw && address(c).balance == contractBalBefore - effectiveWithdraw);
            }
        }
    }

    receive() external payable {}
}

