        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = address(c).balance;
        assertTrue(reverted && balAfter == balBefore);
    }

    function testFuzz_run(uint256 depositAmount, uint256 extra, uint256 withdrawAmount) public {
        _run(depositAmount, extra, withdrawAmount);
    }

    receive() external payable {}
